FILES = json.loads('{"src/engine/decisive/verdict.js": "const HEDGE_PATTERNS = Object.freeze([\n  /可能/g,\n  /也许/g,\n  /或许/g,\n  /倾向于?/g,\n  /值得留意(?:的是)?/g,\n  /继续观察/g,\n  /不宜作确定判断/g,\n  /在保留不确定性的前提下/g,\n]);\n\nconst VERDICTS = Object.freeze({\n  advance: Object.freeze({\n    code: \"advance\",\n    label: \"推进\",\n    directive: \"进入执行，不再等待额外信号。\",\n  }),\n  conditional: Object.freeze({\n    code: \"conditional\",\n    label: \"有条件推进\",\n    directive: \"先核对决定性条件；条件成立就执行，条件不成立就停止。\",\n  }),\n  wait: Object.freeze({\n    code: \"wait\",\n    label: \"等待\",\n    directive: \"现在不作最终投入，等关键事实出现后再决定。\",\n  }),\n  adjust: Object.freeze({\n    code: \"adjust\",\n    label: \"调整\",\n    directive: \"停止沿用当前方法，改变路径后再推进。\",\n  }),\n  stop: Object.freeze({\n    code: \"stop\",\n    label: \"停止\",\n    directive: \"停止新增投入，不继续维持当前方向。\",\n  }),\n  redirect: Object.freeze({\n    code: \"redirect\",\n    label: \"结束并转向\",\n    directive: \"结束当前方向，把资源转向新的选择。\",\n  }),\n});\n\nconst STANCE_GROUP = Object.freeze({\n  supportive: \"positive\",\n  cautionary: \"negative\",\n  conditional: \"conditional\",\n  transformative: \"transformative\",\n  descriptive: \"neutral\",\n});\n\nfunction deepFreeze(value) {\n  if (!value || typeof value !== \"object\" || Object.isFrozen(value)) return value;\n  for (const item of Object.values(value)) deepFreeze(item);\n  return Object.freeze(value);\n}\n\nfunction normalizeText(value) {\n  return String(value || \"\")\n    .replace(/\\s+/g, \"\")\n    .replace(/[，。；：、“”‘’！？,.!?;:()（）【】\\[\\]]/g, \"\")\n    .toLowerCase();\n}\n\nfunction directText(value) {\n  let text = String(value || \"\").replace(/\\s+/g, \" \”).trim();\n  for (const pattern of HEDGE_PATTERNS) text = text.replace(pattern, \"\");\n  return text\n    .replace(/需要结合[^。；]+共同理解/g, \"\")\n    .replace(/现有证据(?:指向|提示)/g, \"\")\n    .replace(/当前(?:更)?(?:适合|偏向)/g, \"\")\n    .replace(/^\\s*[，、；：]\\s*/g, \"\")\n    .replace(/\\s+/g, \" \”)\n    .replace(/[。；;]+$/g, \"\")\n    .trim();\n}\n\nfunction uniqueText(values) {\n  const kept = [];\n  const keys = [];\n  for (const value of values) {\n    const text = directText(value);\n    const key = normalizeText(text);\n    if (!key) continue;\n    if (keys.some((known) => known === key || known.includes(key) || key.includes(known))) continue;\n    kept.push(text);\n    keys.push(key);\n  }\n  return kept;\n}\n\nfunction score(candidate) {\n  return Number(candidate?.score || 0);\n}\n\nfunction totals(candidates) {\n  const result = {\n    positive: 0,\n    negative: 0,\n    conditional: 0,\n    transformative: 0,\n    neutral: 0,\n  };\n  for (const candidate of candidates) {\n    const group = STANCE_GROUP[candidate.stance] || \"neutral\";\n    result[group] += score(candidate);\n  }\n  return result;\n}\n\nfunction fromConclusionType(type) {\n  const value = String(type || \"\");\n  if (/(release|ending|leave|close|redirect|end)/.test(value)) return \"redirect\";\n  if (/(unfavorable|avoid|pause|stop|decline|not-ready|no-)/.test(value)) return \"stop\";\n  if (/(adjust|repair|balance|boundary|review|clarify|change|transform)/.test(value)) return \"adjust\";\n  if (/(wait|prepare|observe|slow)/.test(value)) return \"wait\";\n  if (/(condition|cautious)/.test(value)) return \"conditional\";\n  if (/(act-now|favorable|continue|proceed|open|growth|advance|accept|yes|strengthen)/.test(value)) return \"advance\";\n  return null;\n}\n\nfunction resolveVerdict(claim, candidates) {\n  const mapped = fromConclusionType(claim?.conclusionType);\n  if (mapped && claim?.conclusionCategory !== \"indeterminate\") {\n    if (mapped === \"advance\" && claim?.conditions?.length) return VERDICTS.conditional;\n    return VERDICTS[mapped];\n  }\n\n  const sum = totals(candidates);\n  const ordered = [...candidates].sort((left, right) => (\n    score(right) - score(left)\n    || Number(left.sourceOrder || 0) - Number(right.sourceOrder || 0)\n    || String(left.id).localeCompare(String(right.id))\n  ));\n  const top = ordered[0];\n  if (!top) return VERDICTS.wait;\n\n  if (sum.negative > sum.positive + 0.18) {\n    return sum.negative >= 1.2 || score(top) >= 0.76 ? VERDICTS.stop : VERDICTS.adjust;\n  }\n  if (sum.positive > sum.negative + 0.18) {\n    return sum.conditional >= sum.positive * 0.65 || claim?.conditions?.length\n      ? VERDICTS.conditional\n      : VERDICTS.advance;\n  }\n  if (top.stance === \"supportive\") return claim?.conditions?.length ? VERDICTS.conditional : VERDICTS.advance;\n  if (top.stance === \"cautionary\") return score(top) >= 0.72 ? VERDICTS.stop : VERDICTS.adjust;\n  if (top.stance === \"transformative\") return VERDICTS.adjust;\n  if (top.stance === \"conditional\") return VERDICTS.conditional;\n  return VERDICTS.wait;\n}\n\nfunction strengthFor(candidates) {\n  const grouped = Object.values(totals(candidates)).sort((a, b) => b - a);\n  const first = grouped[0] || 0;\n  const second = grouped[1] || 0;\n  const total = grouped.reduce((sum, value) => sum + value, 0) || 1;\n  const separation = Math.max(0, first - second) / total;\n  return Math.max(55, Math.min(96, Math.round(58 + separation * 95)));\n}\n\nfunction displayForPositions(positionIds, draws) {\n  const byPosition = new Map((draws || []).map((draw) => [draw.positionId, draw]));\n  const selected = positionIds.map((id) => byPosition.get(id)).filter(Boolean);\n  return {\n    positionIds: selected.map((item) => item.positionId),\n    positionName: selected.map((item) => item.positionName).join(\" → \"),\n    cardId: selected.map((item) => item.cardId).join(\"+\"),\n    cardName: selected.map((item) => item.cardName).join(\" / \"),\n    orientation: selected.map((item) => item.orientation === \"reversed\" ? \"逆位\" : \"正位\").join(\" / \"),\n  };\n}\n\nfunction roleFor(stance) {\n  return {\n    supportive: \"推动\",\n    cautionary: \"阻断\",\n    conditional: \"设定门槛\",\n    transformative: \"改变方向\",\n    descriptive: \"界定局面\",\n  }[stance] || \"界定局面\";\n}\n\nfunction createFactors(candidates, draws) {\n  const factors = [];\n  const seen = [];\n  for (const candidate of candidates) {\n    const text = uniqueText(candidate.semanticSeeds || [])[0];\n    if (!text) continue;\n    const key = normalizeText(text);\n    if (seen.some((known) => known === key || known.includes(key) || key.includes(known))) continue;\n    const display = displayForPositions(candidate.positionIds || [], draws);\n    if (!display.positionName || !display.cardName) continue;\n    factors.push({\n      candidateId: candidate.id,\n      positionIds: display.positionIds,\n      positionName: display.positionName,\n      cardId: display.cardId,\n      cardName: display.cardName,\n      orientation: display.orientation,\n      role: roleFor(candidate.stance),\n      text,\n      score: score(candidate),\n    });\n    seen.push(key);\n    if (factors.length === 3) break;\n  }\n  return factors;\n}\n\nfunction createTrajectory(factors) {\n  if (factors.length === 0) return \"牌阵没有形成可用的主导链，结果由等待规则收束。\";\n  if (factors.length === 1) {\n    return `走势由“${factors[0].positionName}”的${factors[0].cardName}单点定向，作用是${factors[0].role}。`;\n  }\n  if (factors.length === 2) {\n    return `走势先由“${factors[0].positionName}”定调，再由“${factors[1].positionName}”完成${factors[1].role}。`;\n  }\n  return `走势从“${factors[0].positionName}”起步，经“${factors[1].positionName}”转折，最终由“${factors[2].positionName}”收束。`;\n}\n\nfunction oppositeStances(code) {\n  if ([\"advance\", \"conditional\"].includes(code)) return new Set([\"cautionary\"]);\n  if ([\"stop\", \"redirect\"].includes(code)) return new Set([\"supportive\"]);\n  if (code === \"adjust\") return new Set([\"supportive\", \"cautionary\"]);\n  return new Set([\"supportive\", \"cautionary\", \"transformative\"]);\n}\n\nfunction createChangeCondition(verdict, candidates, factorIds) {\n  const wanted = oppositeStances(verdict.code);\n  const opposing = candidates.find((candidate) => (\n    wanted.has(candidate.stance)\n    && !factorIds.has(candidate.id)\n    && uniqueText(candidate.semanticSeeds || []).length\n  ));\n  if (!opposing) {\n    return \"当前牌阵无改判条件；只有现实前提发生实质变化，才需要重新起牌。\";\n  }\n  const seed = uniqueText(opposing.semanticSeeds)[0];\n  return `只有当“${seed}”成为现实中的主导事实，当前判断才会改变。`;\n}\n\nexport function validateDecisiveInterpretation(result) {\n  const errors = [];\n  if (!result?.verdict?.code || !VERDICTS[result.verdict.code]) errors.push(\"A single decisive verdict is required.\");\n  const visible = [\n    result?.judgment,\n    result?.trajectory,\n    result?.changeCondition,\n    ...(result?.decisiveFactors || []).map((item) => item.text),\n  ].join(\"\\n\");\n  for (const pattern of HEDGE_PATTERNS) {\n    pattern.lastIndex = 0;\n    if (pattern.test(visible)) errors.push(`Hedge phrase leaked: ${pattern}`);\n  }\n  const factorKeys = (result?.decisiveFactors || []).map((item) => normalizeText(item.text));\n  if (new Set(factorKeys).size !== factorKeys.length) errors.push(\"Decisive factors contain duplicate text.\");\n  if ((result?.decisiveFactors || []).length > 3) errors.push(\"Too many decisive factors.\");\n  return errors;\n}\n\nexport function createDecisiveInterpretation({\n  engineResult,\n  questionText,\n  draws,\n} = {}) {\n  if (!engineResult?.claim || !engineResult?.resolution) {\n    throw new TypeError(\"Structured engine result is required.\");\n  }\n  const candidates = [...(engineResult.resolution.activeCandidates || [])].sort((left, right) => (\n    score(right) - score(left)\n    || Number(left.sourceOrder || 0) - Number(right.sourceOrder || 0)\n    || String(left.id).localeCompare(String(right.id))\n  ));\n  const verdict = resolveVerdict(engineResult.claim, candidates);\n  const decisiveFactors = createFactors(candidates, draws || []);\n  const result = {\n    schemaVersion: \"2.0.0\",\n    verdict: {\n      ...verdict,\n      strength: strengthFor(candidates),\n      rule: \"net-score-evidence-coverage-stable-order\",\n    },\n    judgment: `对“${directText(questionText) || \"当前问题\"}”的判定：${verdict.label}。${verdict.directive}`,\n    trajectory: createTrajectory(decisiveFactors),\n    decisiveFactors,\n    changeCondition: createChangeCondition(\n      verdict,\n      candidates,\n      new Set(decisiveFactors.map((item) => item.candidateId)),\n    ),\n    provenance: {\n      claimId: engineResult.claim.id,\n      activeCandidateCount: candidates.length,\n      verdictRule: \"net-score-evidence-coverage-stable-order\",\n    },\n  };\n  const errors = validateDecisiveInterpretation(result);\n  if (errors.length) throw new Error(errors.join(\"; \"));\n  return deepFreeze(result);\n}\n\nexport { HEDGE_PATTERNS, VERDICTS };\n", "src/engine/decisive/reading.js": "import { executeReadingEngine } from \"../runtime/reading-engine.js\";\nimport { createDecisiveInterpretation } from \"./verdict.js\";\n\nfunction deepFreeze(value) {\n  if (!value || typeof value !== \"object\" || Object.isFrozen(value)) return value;\n  for (const item of Object.values(value)) deepFreeze(item);\n  return Object.freeze(value);\n}\n\nexport async function executeDecisiveReading({\n  questionId,\n  questionText,\n  spreadId,\n  draws,\n} = {}) {\n  const engineResult = await executeReadingEngine({\n    questionId,\n    spreadId,\n    draws: (draws || []).map((draw) => ({\n      cardId: draw.cardId,\n      positionId: draw.positionId,\n      orientation: draw.orientation,\n    })),\n    renderingStream: null,\n  });\n  const synthesis = createDecisiveInterpretation({\n    engineResult,\n    questionText,\n    draws,\n  });\n  return deepFreeze({ synthesis, engineResult });\n}\n", "src/workers/reading-engine.worker.js": "import { executeDecisiveReading } from \"../engine/decisive/reading.js\";\n\nself.addEventListener(\"message\", async (event) => {\n  const message = event.data || {};\n  if (message.type !== \"ASTRA_SYNTHESIZE_READING\" || !message.id) return;\n  try {\n    const value = await executeDecisiveReading(message.payload);\n    self.postMessage({\n      id: message.id,\n      status: \"completed\",\n      value,\n    });\n  } catch (error) {\n    self.postMessage({\n      id: message.id,\n      status: \"failed\",\n      error: {\n        name: error?.name || \"Error\",\n        message: error?.message || \"Reading worker failed.\",\n      },\n    });\n  }\n});\n", "src/app/engine-worker-client.js": "const WORKER_MESSAGE = \"ASTRA_SYNTHESIZE_READING\";\n\nexport function createReadingEngineWorkerClient({\n  WorkerRef = globalThis.Worker,\n  workerUrl = new URL(\"../workers/reading-engine.worker.js\", import.meta.url),\n  timeoutMs = 30000,\n} = {}) {\n  let worker = null;\n  let sequence = 0;\n  const pending = new Map();\n\n  function failAll(error) {\n    for (const item of pending.values()) {\n      clearTimeout(item.timer);\n      item.reject(error);\n    }\n    pending.clear();\n  }\n\n  function ensureWorker() {\n    if (worker) return worker;\n    if (typeof WorkerRef !== \"function\") {\n      throw new Error(\"当前浏览器不支持模块 Worker，无法执行牌面推理。\");\n    }\n    worker = new WorkerRef(workerUrl, {\n      type: \"module\",\n      name: \"astra-reading-engine\",\n    });\n    worker.addEventListener(\"message\", (event) => {\n      const message = event.data || {};\n      const item = pending.get(message.id);\n      if (!item) return;\n      clearTimeout(item.timer);\n      pending.delete(message.id);\n      if (message.status === \"completed\") {\n        item.resolve(message.value);\n      } else {\n        const error = new Error(message.error?.message || \"牌面推理失败。\");\n        error.name = message.error?.name || \"ReadingWorkerError\";\n        item.reject(error);\n      }\n    });\n    worker.addEventListener(\"error\", () => {\n      failAll(new Error(\"牌面推理 Worker 已终止。\"));\n      worker?.terminate?.();\n      worker = null;\n    });\n    return worker;\n  }\n\n  function synthesize(payload) {\n    const activeWorker = ensureWorker();\n    const id = `reading-${Date.now()}-${sequence += 1}`;\n    return new Promise((resolve, reject) => {\n      const timer = setTimeout(() => {\n        pending.delete(id);\n        reject(new Error(\"牌面推理超时。\"));\n      }, timeoutMs);\n      pending.set(id, { resolve, reject, timer });\n      activeWorker.postMessage({\n        type: WORKER_MESSAGE,\n        id,\n        payload,\n      });\n    });\n  }\n\n  function dispose() {\n    failAll(new Error(\"牌面推理 Worker 已关闭。\"));\n    worker?.terminate?.();\n    worker = null;\n  }\n\n  return Object.freeze({ synthesize, dispose });\n}\n\nexport { WORKER_MESSAGE };\n", "src/app/controllers/engine-synthesis.js": "function serializeDraw(draw) {\n  return {\n    cardId: draw.card.id,\n    cardName: draw.card.name,\n    positionId: draw.position.id,\n    positionName: draw.position.name,\n    orientation: draw.reversed ? \"reversed\" : \"upright\",\n  };\n}\n\nexport function serializeReadingForWorker(reading) {\n  if (!reading?.question?.id || !reading?.spread?.id || !Array.isArray(reading.draws)) {\n    throw new TypeError(\"Complete reading input is required.\");\n  }\n  return {\n    questionId: reading.question.id,\n    questionText: reading.question.text,\n    spreadId: reading.spread.id,\n    draws: reading.draws.map(serializeDraw),\n  };\n}\n\nexport function createEngineSynthesis({ workerClient } = {}) {\n  if (!workerClient?.synthesize) throw new TypeError(\"Reading Engine Worker client is required.\");\n  return (reading) => workerClient.synthesize(serializeReadingForWorker(reading));\n}\n", "src/app/controllers/phase-8-runtime.js": "import { createRecoveryActions } from \"../recovery/recovery-actions.js\";\nimport { createRecoveryCoordinator } from \"../recovery/recovery-coordinator.js\";\nimport { createDiagnosticLog } from \"../../platform/diagnostics.js\";\nimport { createStructuredHistorySummary } from \"../../storage/history-summary.js\";\nimport { installAccessibility } from \"../../ui/accessibility/controller.js\";\nimport { renderRecoveryPanel } from \"../../ui/components/recovery-panel.js\";\n\nexport function createPhase8Runtime({\n  windowRef,\n  documentRef,\n  dom,\n  showToast,\n  retry,\n  saveStructuredReading,\n  synthesizeReading,\n} = {}) {\n  if (!windowRef || !documentRef || !dom) throw new TypeError(\"Phase 8 runtime requires browser bindings.\");\n  if (typeof synthesizeReading !== \"function\") throw new TypeError(\"Worker-backed reading synthesis is required.\");\n  const diagnostics = createDiagnosticLog();\n  let actions;\n  const recovery = createRecoveryCoordinator({\n    diagnosticLog: diagnostics,\n    onError(error) {\n      renderRecoveryPanel({\n        documentRef,\n        container: dom.insightContent,\n        error,\n        onAction: (action) => void actions.handle(action),\n      });\n    },\n  });\n  actions = createRecoveryActions({\n    windowRef,\n    documentRef,\n    diagnosticLog: diagnostics,\n    retry,\n    showToast,\n  });\n  installAccessibility({ dom });\n\n  async function synthesize(reading) {\n    const result = await recovery.execute(\n      \"engine\",\n      () => synthesizeReading(reading),\n      { spreadId: reading?.spread?.id, stage: \"complete-reading\" },\n    );\n    if (result.status !== \"completed\") return null;\n    Object.defineProperty(reading, \"engineResult\", {\n      value: result.value.engineResult,\n      enumerable: false,\n      configurable: true,\n    });\n    return result.value.synthesis;\n  }\n\n  function enrichLegacyRecord(record, reading) {\n    const structured = createStructuredHistorySummary(reading?.engineResult);\n    if (structured) record.structured = structured;\n    return record;\n  }\n\n  async function saveStructured(reading) {\n    const result = await saveStructuredReading(reading, reading?.engineResult || null);\n    if (result.status === \"degraded\") showToast(\"结构化历史暂存于内存，请及时导出\", \"!\");\n    return result;\n  }\n\n  return Object.freeze({ synthesize, enrichLegacyRecord, saveStructured, diagnostics });\n}\n", "src/ui/renderers/insight.js": "import { accentToken } from \"../../config/accent-tokens.js\";\nimport { resolveDeckStyle } from \"../../config/decks.js\";\nimport { escapeHtml } from \"../../core/html.js\";\nimport { cardImagePath } from \"../../platform/assets.js\";\n\nfunction scrollTop(dom) {\n  requestAnimationFrame(() => {\n    dom.insightContent.scrollTop = 0;\n  });\n}\n\nfunction factorForPosition(synthesis, positionId) {\n  return synthesis?.decisiveFactors?.find((factor) => factor.positionIds.includes(positionId)) || null;\n}\n\nexport function createInsightRenderer({\n  dom,\n  state,\n  currentDeckStyle,\n} = {}) {\n  function renderCardInsight(index) {\n    if (!state.reading) return;\n    const draw = state.reading.draws[index];\n    const { card, reversed, position } = draw;\n    const deckStyle = resolveDeckStyle(state.reading.deckStyle || currentDeckStyle());\n    const orientation = reversed ? \"逆位\" : \"正位\";\n    const meaning = reversed ? card.reversed : card.upright;\n    const factor = factorForPosition(state.reading.synthesis, position.id);\n    const directMeaning = factor?.text || meaning;\n    const role = factor?.role || (reversed ? \"阻断\" : \"推动\");\n\n    dom.insightContent.innerHTML = `\n      <article class=\"card-reading\">\n        <header class=\"selected-card-heading\">\n          <div class=\"mini-card deck-style-${deckStyle.id} ${reversed ? \"is-reversed\" : \"\"}\" data-accent-token=\"${accentToken(card.accent)}\">\n            <img src=\"${cardImagePath(card.id, deckStyle)}\" alt=\"\" />\n          </div>\n          <div class=\"selected-card-copy\">\n            <span class=\"position-overline\">${String(index + 1).padStart(2, \"0\")} · ${escapeHtml(position.name)}</span>\n            <h3>${escapeHtml(card.name)}</h3>\n            <p>${escapeHtml(card.en)}</p>\n            <span class=\"orientation-badge ${reversed ? \"is-reversed\" : \"\"}\">\n              ${reversed ? \"↧\" : \"↥\"} ${orientation}\n            </span>\n          </div>\n        </header>\n\n        <section class=\"reading-block\">\n          <div class=\"reading-block-label\">牌位判词</div>\n          <p>${escapeHtml(`${position.name}由${card.name}${orientation}定调：${directMeaning}`)}</p>\n        </section>\n\n        <section class=\"reading-block\">\n          <div class=\"reading-block-label\">在牌阵中的作用</div>\n          <div class=\"position-context\">\n            <strong>${escapeHtml(role)}</strong>\n            <p>${escapeHtml(position.prompt)}</p>\n          </div>\n        </section>\n      </article>\n    `;\n    scrollTop(dom);\n  }\n\n  function renderSummary() {\n    if (!state.reading?.synthesis) return;\n    const { synthesis, category } = state.reading;\n    const factors = synthesis.decisiveFactors.map((factor) => `\n      <li>\n        <strong>${escapeHtml(`${factor.positionName} · ${factor.cardName} ${factor.orientation}`)}</strong>\n        <span>${escapeHtml(factor.role)}</span>\n        <p>${escapeHtml(factor.text)}</p>\n      </li>\n    `).join(\"\");\n\n    dom.insightContent.innerHTML = `\n      <article class=\"summary-reading decisive-reading\" data-accent-token=\"${accentToken(category.accent)}\">\n        <header class=\"summary-hero\">\n          <span class=\"summary-overline\">FINAL JUDGMENT · 最终判断</span>\n          <h3>${escapeHtml(synthesis.verdict.label)}</h3>\n          <p>${escapeHtml(synthesis.judgment)}</p>\n        </header>\n\n        <section class=\"reading-block\">\n          <div class=\"reading-block-label\">走势依据</div>\n          <p>${escapeHtml(synthesis.trajectory)}</p>\n        </section>\n\n        <section class=\"reading-block\">\n          <div class=\"reading-block-label\">决定性牌位</div>\n          <ul class=\"summary-list decisive-factor-list\">${factors}</ul>\n        </section>\n\n        <section class=\"reading-block\">\n          <div class=\"reading-block-label\">改判条件</div>\n          <p>${escapeHtml(synthesis.changeCondition)}</p>\n        </section>\n      </article>\n    `;\n    scrollTop(dom);\n  }\n\n  return Object.freeze({ renderCardInsight, renderSummary });\n}\n", "src/app/platform-runtime.js": "export function createPlatformRuntime({\n  windowRef,\n  offlineStatus,\n  registerServiceWorker,\n  state,\n} = {}) {\n  let coordinator = null;\n  let updatePending = false;\n\n  function clientState() {\n    if (state.completing) return \"pending-save\";\n    if (state.phase === \"setup\" || state.phase === \"complete\") return \"idle\";\n    return \"reading\";\n  }\n\n  async function activateWhenIdle() {\n    coordinator?.reportState?.();\n    if (!updatePending || !coordinator || clientState() !== \"idle\") return false;\n    const decision = await coordinator.requestActivation({ force: false });\n    if (decision?.activated) updatePending = false;\n    return Boolean(decision?.activated);\n  }\n\n  async function start(selectedDeckId) {\n    const result = await registerServiceWorker({\n      getClientState: clientState,\n      getCurrentReleaseId: () => offlineStatus.getStatus().activeReleaseId,\n      onUpdateAvailable() {\n        updatePending = true;\n        void activateWhenIdle();\n      },\n      onActivated() {\n        windowRef?.location?.reload?.();\n      },\n    });\n    coordinator = result.coordinator;\n    offlineStatus.start({ selectedDeckId });\n    void activateWhenIdle();\n    return result;\n  }\n\n  function render() {\n    void activateWhenIdle();\n  }\n\n  return Object.freeze({ start, render });\n}\n", "src/ui/dom.js": "const REQUIRED_IDS = Object.freeze([\n  \"brandHome\", \"categoryGrid\", \"categoryTagline\", \"questionPickerButton\",\n  \"selectedQuestionLabel\", \"selectedQuestionText\", \"questionList\", \"questionDialog\",\n  \"questionDialogHint\", \"spreadList\", \"deckStyleList\", \"startReading\", \"readingKicker\",\n  \"readingTitle\", \"readingMeta\", \"metaCategory\", \"metaSpread\", \"readingStage\", \"idleState\",\n  \"idleDeckImage\", \"shuffleScene\", \"shuffleDeck\", \"shufflePhase\", \"shuffleProgress\",\n  \"cardTable\", \"stageGuidance\", \"guidanceText\", \"statusText\", \"insightTabs\",\n  \"insightContent\", \"newReadingButton\", \"revealAllButton\", \"historyButton\", \"helpButton\",\n  \"historyDialog\", \"helpDialog\", \"confirmDialog\", \"confirmTitle\", \"confirmMessage\",\n  \"confirmAccept\", \"historyList\", \"clearHistoryButton\", \"toastRegion\", \"installButton\",\n]);\n\nexport function bindDom(documentRef = globalThis.document) {\n  if (!documentRef) throw new Error(\"DOM bindings require a document.\");\n  const bindings = {};\n  for (const id of REQUIRED_IDS) {\n    const element = documentRef.getElementById(id);\n    if (!element) throw new Error(`Required DOM element is missing: #${id}`);\n    bindings[id] = element;\n  }\n  const readingPanel = documentRef.querySelector(\".reading-panel\");\n  if (!readingPanel) throw new Error(\"Required DOM element is missing: .reading-panel\");\n  bindings.readingPanel = readingPanel;\n  return Object.freeze(bindings);\n}\n", "tests/phase_10_decisive_worker_test.mjs": "import assert from \"node:assert/strict\";\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nimport {\n  createDecisiveInterpretation,\n  validateDecisiveInterpretation,\n} from \"../src/engine/decisive/verdict.js\";\nimport {\n  createReadingEngineWorkerClient,\n  WORKER_MESSAGE,\n} from \"../src/app/engine-worker-client.js\";\n\nconst root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), \"..\");\n\nconst engineResult = {\n  claim: {\n    id: \"claim-test\",\n    conclusionType: \"indeterminate\",\n    conclusionCategory: \"indeterminate\",\n    conditions: [],\n  },\n  resolution: {\n    activeCandidates: [\n      {\n        id: \"candidate-support\",\n        score: 0.84,\n        sourceOrder: 0,\n        stance: \"supportive\",\n        positionIds: [\"present\"],\n        semanticSeeds: [\"行动条件已经成熟\"],\n      },\n      {\n        id: \"candidate-risk\",\n        score: 0.63,\n        sourceOrder: 1,\n        stance: \"cautionary\",\n        positionIds: [\"obstacle\"],\n        semanticSeeds: [\"旧方法正在消耗可用资源\"],\n      },\n      {\n        id: \"candidate-repeat\",\n        score: 0.51,\n        sourceOrder: 2,\n        stance: \"descriptive\",\n        positionIds: [\"present\"],\n        semanticSeeds: [\"行动条件已经成熟。\"],\n      },\n    ],\n  },\n};\nconst draws = [\n  {\n    cardId: \"major-1\",\n    cardName: \"魔术师\",\n    positionId: \"present\",\n    positionName: \"当前\",\n    orientation: \"upright\",\n  },\n  {\n    cardId: \"major-16\",\n    cardName: \"高塔\",\n    positionId: \"obstacle\",\n    positionName: \"阻碍\",\n    orientation: \"reversed\",\n  },\n];\n\nconst first = createDecisiveInterpretation({\n  engineResult,\n  questionText: \"这件事现在应该推进吗？\",\n  draws,\n});\nconst second = createDecisiveInterpretation({\n  engineResult,\n  questionText: \"这件事现在应该推进吗？\",\n  draws,\n});\nassert.deepEqual(first, second);\nassert.notEqual(first.verdict.code, \"indeterminate\");\nassert.equal(first.verdict.code, \"advance\");\nassert.equal(first.decisiveFactors.length, 2);\nassert.deepEqual(validateDecisiveInterpretation(first), []);\nassert.equal(/可能|也许|倾向|值得留意|继续观察|不宜作确定判断/.test(JSON.stringify(first)), false);\n\nclass FakeWorker {\n  constructor(url, options) {\n    this.url = url;\n    this.options = options;\n    this.listeners = new Map();\n  }\n  addEventListener(name, listener) {\n    this.listeners.set(name, listener);\n  }\n  postMessage(message) {\n    assert.equal(message.type, WORKER_MESSAGE);\n    queueMicrotask(() => {\n      this.listeners.get(\"message\")?.({\n        data: {\n          id: message.id,\n          status: \"completed\",\n          value: { synthesis: first, engineResult },\n        },\n      });\n    });\n  }\n  terminate() {}\n}\nconst client = createReadingEngineWorkerClient({\n  WorkerRef: FakeWorker,\n  workerUrl: new URL(\"file:///reading-engine.worker.js\"),\n  timeoutMs: 1000,\n});\nconst workerResult = await client.synthesize({ questionId: \"q\", spreadId: \"single\", draws: [] });\nassert.equal(workerResult.synthesis.verdict.code, \"advance\");\nclient.dispose();\n\nconst index = fs.readFileSync(path.join(root, \"index.html\"), \"utf8\");\nconst dom = fs.readFileSync(path.join(root, \"src/ui/dom.js\"), \"utf8\");\nconst application = fs.readFileSync(path.join(root, \"src/app/application.js\"), \"utf8\");\nconst adapter = fs.readFileSync(path.join(root, \"src/app/controllers/engine-synthesis.js\"), \"utf8\");\nconst workerClient = fs.readFileSync(path.join(root, \"src/app/engine-worker-client.js\"), \"utf8\");\nconst insight = fs.readFileSync(path.join(root, \"src/ui/renderers/insight.js\"), \"utf8\");\n\nfor (const removed of [\n  \"platformStatus\",\n  \"offlineState\",\n  \"releaseState\",\n  \"storageState\",\n  \"cacheDeckButton\",\n  \"deleteDeckButton\",\n  \"updateAppButton\",\n]) {\n  assert.equal(index.includes(`id=\"${removed}\"`), false, removed);\n  assert.equal(dom.includes(`\"${removed}\"`), false, removed);\n}\nfor (const heading of [\"牌阵故事\", \"牌与牌之间如何对话\", \"你可以留意\", \"接下来的三步\"]) {\n  assert.equal(application.includes(heading), false, heading);\n  assert.equal(insight.includes(heading), false, heading);\n}\nassert.equal(adapter.includes(\"engine/runtime/reading-engine.js\"), false);\nassert.match(application, /createReadingEngineWorkerClient/);\nassert.match(workerClient, /type:\\s*\"module\"/);\nassert.match(workerClient, /new WorkerRef/);\nassert.match(application, /createInsightRenderer/);\n\nconsole.log(\"Phase 10 decisive reading contract passed: visible status UI is removed, verdicts are unique, text is non-repetitive, and engine work crosses a module Worker boundary.\");\n", "tests/phase_10_gate_test.mjs": "import assert from \"node:assert/strict\";\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), \"..\");\nconst progress = fs.readFileSync(path.join(root, \"docs/PROGRESS.md\"), \"utf8\");\nconst phase = fs.readFileSync(path.join(root, \"docs/PHASE_10_DECISIVE_READING.md\"), \"utf8\");\nconst index = fs.readFileSync(path.join(root, \"index.html\"), \"utf8\");\nconst application = fs.readFileSync(path.join(root, \"src/app/application.js\"), \"utf8\");\n\nassert.match(progress, /Phase 10状态 \\| `PARENT-DONE`/);\nassert.match(progress, /唯一下一任务 \\| `无（2\\.1解读重构终态）`/);\nassert.match(phase, /最终判断/);\nassert.match(phase, /模块 Web Worker/);\nassert.equal(index.includes(\"class=\\\"platform-status\\\"\"), false);\nassert.equal(application.includes(\"executeReadingEngine\"), false);\n\nconsole.log(\"Phase 10 terminal gate passed: decisive Worker-backed reading is the recorded terminal state.\");\n", "docs/PROGRESS.md": "# 项目开发进度\n\n> 本文件是继续任务的唯一实时状态入口；任务定义以 `EXECUTION_CONTRACTS.md` 为准。\n\n## 当前状态\n\n| 项目 | 当前值 |\n|---|---|\n| 当前阶段 | Phase 10：确定性解读与主线程解耦 |\n| 当前进行中任务 | 无 |\n| 最近完成任务 | Phase 10终态：确定性解读、状态面板移除、Worker推理 |\n| 唯一下一任务 | `无（2.1解读重构终态）` |\n| 阻塞项 | 无 |\n| 工作分支 | `phase-10-decisive-worker` |\n| Phase M状态 | `PARENT-DONE` |\n| Phase 1状态 | `PARENT-DONE` |\n| Phase 2状态 | `PARENT-DONE` |\n| Phase 3状态 | `PARENT-DONE` |\n| Phase 4状态 | `PARENT-DONE` |\n| Phase 5状态 | `PARENT-DONE` |\n| Phase 6状态 | `PARENT-DONE` |\n| Phase 7状态 | `PARENT-DONE` |\n| Phase 8状态 | `PARENT-DONE` |\n| Phase 9状态 | `PARENT-DONE` |\n| Phase 10状态 | `PARENT-DONE` |\n| 最后更新时间 | 2026-08-01 |\n\n## Phase 10完成记录\n\n- 删除设置页离线状态、版本、存储空间、页面状态、缓存和安全更新面板。\n- Service Worker、离线缓存和安全激活继续在后台运行，不向用户展示维护信息。\n- 综合解读改为“最终判断、走势依据、决定性牌位、改判条件”。\n- 删除牌阵故事、牌间对话、留意事项、三步建议、固定追问和固定套话。\n- 冲突和未决通过净分、证据覆盖与稳定来源顺序产生唯一决断。\n- 用户可见总结禁止模糊词和标准化重复句。\n- 完整资料加载、Observation、Relation、Claim和判词生成移入模块 Web Worker。\n- UI主线程只发送可序列化输入并渲染可序列化结果。\n- 卡牌发牌动画批量读取布局，避免逐牌读写交错。\n- 阶段实现CWapi任务：`__IMPLEMENTATION_TASK__`。\n- 最终full复验CWapi任务：`__FINAL_TASK__`；最终commit以终态RESULT和远端分支核验为准。\n\n## 冻结不变量\n\n- 运行时纯规则、离线、固定问题和四牌阵。\n- 确定性表示同一输入在固定规则下产生唯一结果，不宣称对现实未来具有客观必然性。\n- Worker失败不在UI主线程静默重跑完整引擎。\n- 抽牌、正逆位和推理输入保持可审计。\n- 最终盲测正文不进入仓库或日志。\n- `automation/validate.py --scope full` 是完整回归入口。\n", "src/styles/phase-10.css": ".decisive-reading .summary-hero {\n  padding-bottom: 1.1rem;\n}\n\n.decisive-reading .summary-hero h3 {\n  font-size: clamp(1.7rem, 2.5vw, 2.45rem);\n  letter-spacing: 0.08em;\n}\n\n.decisive-reading .summary-hero p {\n  max-width: 38rem;\n  font-size: 1rem;\n  line-height: 1.85;\n}\n\n.decisive-factor-list {\n  display: grid;\n  gap: 0.75rem;\n}\n\n.decisive-factor-list li {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  gap: 0.25rem 0.75rem;\n  padding: 0.85rem 0.95rem;\n  border: 1px solid rgb(255 255 255 / 8%);\n  border-radius: 0.8rem;\n  background: rgb(255 255 255 / 3%);\n}\n\n.decisive-factor-list strong {\n  color: var(--text-primary);\n  font-size: 0.94rem;\n}\n\n.decisive-factor-list span {\n  color: var(--accent-color, var(--gold));\n  font-size: 0.78rem;\n  letter-spacing: 0.08em;\n}\n\n.decisive-factor-list p {\n  grid-column: 1 / -1;\n  margin: 0.25rem 0 0;\n  color: var(--text-secondary);\n  line-height: 1.7;\n}\n"}')


def write_lf(relative: str, content: str) -> None:
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="\n") as handle:
        handle.write(content.rstrip() + "\n")


for relative, content in FILES.items():
    write_lf(relative, content)

